const base = $('Build Quote Context').item.json || {};
const out = $input.first().json.output || '';
let s = String(out).trim().replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
let subject = 'Your catering quote';
let body = String(out);
try { const p = JSON.parse(s); subject = p.subject || subject; body = p.body || body; } catch (e) {}
return [{json: Object.assign({}, base, {quote_subject: subject, quote_body: body})}];

const j = $input.first().json;
const out = {found: false, event_id: j.in_event_id, field: j.in_field, value: j.in_value, client_name: '', client_email: ''};
if (j.evjson) {
  try { const r = JSON.parse(j.evjson); out.found = true; out.ev = r; out.client_name = r.client_name; out.client_email = r.client_email; } catch (e) {}
}
return [out];

const j = $input.first().json;
const r = j.ev || {};
const field = String(j.field || '').trim();
const value = String(j.value || '').trim();
const isDeposit = (field === 'deposit_status') && (value.toLowerCase() === 'received');
let full_query = '';
let all_params = [];
let subject = '';
let body = '';
let tg_text = '';
let update_type = 'change';
if (isDeposit) {
  update_type = 'deposit';
  full_query = "UPDATE catering_events SET deposit_status = 'received', status = 'confirmed', updated_at = NOW() WHERE event_id = $1::text RETURNING event_id, client_name, client_email, $2::text AS subj, $3::text AS bod, $4::text AS tgtext, $5::text AS ctype;";
  all_params = [j.event_id, subject, body, tg_text, update_type];
  subject = 'Deposit received: ' + (r.event_type || 'your event') + ' is secured';
  body = 'Hi ' + (r.client_name || 'there') + ',\n\nWe received your deposit for your ' + (r.event_type || '') + ' event on ' + (r.event_date || '') + '. Your date is secured and we are locking in the plan.\n\nFinal headcount is due 7 days before the event, and the balance is settled on the day. Reply to this email anytime.\n\nBest regards,\nThe Catering Team';
  tg_text = 'Deposit received for ' + j.event_id + ' (' + (r.client_name || '') + ', ' + (r.event_date || '') + '). Event confirmed.';
  all_params = [j.event_id, subject, body, tg_text, update_type];
} else {
  const whitelist = {guest_count:'guest_count', menu_notes:'menu_notes', venue:'venue', event_date:'event_date', event_type:'event_type', client_name:'client_name', budget_range:'budget_range'};
  const col = whitelist[field] || 'menu_notes';
  let cast = 'text';
  if (col === 'guest_count') cast = 'int';
  if (col === 'event_date') cast = 'date';
  const setval = (col === 'guest_count') ? Number(value) : value;
  full_query = "UPDATE catering_events SET " + col + " = $1::" + cast + ", status = 'confirmed', updated_at = NOW() WHERE event_id = $2::text RETURNING event_id, client_name, client_email, $3::text AS subj, $4::text AS bod, $5::text AS tgtext, $6::text AS ctype;";
  subject = 'We updated your event details';
  body = 'Hi ' + (r.client_name || 'there') + ',\n\nWe have updated your ' + (r.event_type || '') + ' event on ' + (r.event_date || '') + ': ' + field + ' is now ' + value + '.\n\nReply to this email if anything looks off.\n\nBest regards,\nThe Catering Team';
  tg_text = 'Event update for ' + j.event_id + ': ' + field + ' changed to ' + value + ' (' + (r.client_name || '') + ').';
  all_params = [setval, j.event_id, subject, body, tg_text, update_type];
}
return [{json: {event_id: j.event_id, client_name: r.client_name, client_email: r.client_email, update_type: update_type, full_query: full_query, all_params: all_params, subject: subject, body: body, tg_text: tg_text}}];

const j = $input.first().json;
const out = {found: false, event_id: j.in_event_id, final_headcount: j.in_headcount, client_name: '', client_email: ''};
if (j.evjson) {
  try { const r = JSON.parse(j.evjson); out.found = true; out.ev = r; out.client_name = r.client_name; out.client_email = r.client_email; } catch (e) {}
}
return [out];

const j = $input.first().json;
const r = j.ev || {};
const summary = ("Event: " + j.event_id
  + "\nClient: " + (r.client_name || '-')
  + "\nEvent type: " + (r.event_type || '-')
  + "\nEvent date: " + (r.event_date || '-')
  + "\nGuest count as quoted: " + (r.guest_count || '-')
  + "\nFinal headcount: " + j.final_headcount
  + "\nBudget range: " + (r.budget_range || '-')
  + "\nDeposit status: " + (r.deposit_status || '-')
  + "\nVenue: " + (r.venue || '-'));
return [{json: {event_id: j.event_id, final_headcount: j.final_headcount, client_name: r.client_name, client_email: r.client_email, event_type: r.event_type, event_date: r.event_date, budget_range: r.budget_range, event_summary: summary}}];

const base = $('Build Invoice Context').item.json || {};
const out = $input.first().json.output || '';
let s = String(out).trim().replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/\s*```$/, '');
const res = {invoice_subject: 'Your final invoice for ' + (base.event_id || ''), invoice_body: String(out), review_subject: 'How was your event?', review_body: ''};
try { const p = JSON.parse(s); res.invoice_subject = p.invoice_subject || res.invoice_subject; res.invoice_body = p.invoice_body || res.invoice_body; res.review_subject = p.review_subject || res.review_subject; res.review_body = p.review_body || res.review_body; } catch (e) {}
return [{json: Object.assign({}, base, res)}];

const j = $input.first().json;
let evs = [];
try { evs = JSON.parse(j.evs || '[]'); } catch (e) {}
const todayISO = $now.toFormat('yyyy-MM-dd');
const today = Date.parse(todayISO);
const day = 86400000;
const actions = [];
for (const r of evs) {
  let days = null;
  if (r.event_date) {
    const d = Date.parse(String(r.event_date).slice(0, 10));
    if (!isNaN(d)) days = Math.ceil((d - today) / day);
  }
  let nudgeAt = 0;
  if (r.last_nudge_at) { const n = Date.parse(String(r.last_nudge_at).slice(0, 10)); if (!isNaN(n)) nudgeAt = n; }
  const depositPending = String(r.deposit_status || '') === 'pending';
  const depositOverdue = depositPending && days !== null && days >= 0 && days <= 7 && (!nudgeAt || (today - nudgeAt) > 2 * day);
  const common = {event_id: r.event_id || '', client_name: r.client_name || '', client_email: r.client_email || '',
                  event_type: r.event_type || '', event_date: r.event_date || '', guest_count: r.guest_count || 0, venue: r.venue || ''};
  if (days === 7) {
    actions.push(Object.assign({}, common, {
      kind: 't7',
      subject: 'Confirm final headcount: ' + (r.event_type || 'event') + ' on ' + (r.event_date || ''),
      body: 'Hi ' + (r.client_name || 'there') + ',\n\nYour ' + (r.event_type || '') + ' event on ' + (r.event_date || '') + ' is one week away. Please confirm your final headcount by replying to this email.\n\nWe finalize food, staff and transport at this number, so the sooner you confirm, the better.\n\nBest regards,\nThe Catering Team',
      tg_text: 'T-7 for ' + (r.event_id || '') + ': final headcount request sent to ' + (r.client_name || '') + '.',
      comm_type: 't7', direction: 'to_client', has_email: true, _nudge: false}));
  } else if (days === 3) {
    actions.push(Object.assign({}, common, {
      kind: 't3',
      subject: 'Prep reminder: ' + (r.event_type || 'event') + ' on ' + (r.event_date || ''),
      body: 'Hi ' + (r.client_name || 'there') + ',\n\nThree days to go until your ' + (r.event_type || '') + ' event on ' + (r.event_date || '') + '. We are locking in the final plan now. Reply with any last changes to the menu or guest count.\n\nBest regards,\nThe Catering Team',
      tg_text: 'T-3 for ' + (r.event_id || '') + ': prep reminder sent to ' + (r.client_name || '') + '. Finalize the run sheet.',
      comm_type: 't3', direction: 'to_client', has_email: true, _nudge: false}));
  } else if (days === 1) {
    actions.push(Object.assign({}, common, {
      kind: 't1', subject: '', body: '',
      tg_text: 'T-1 tomorrow: ' + (r.event_id || '') + ' ' + (r.event_type || '') + ' for ' + (r.client_name || '') + (r.venue ? ' at ' + r.venue : '') + ' (' + (r.guest_count || '?') + ' guests). Check staff, food prep and transport.',
      comm_type: 't1', direction: 'to_owner', has_email: false, _nudge: false}));
  } else if (days !== null && days >= 0 && days <= 7 && depositOverdue) {
    actions.push(Object.assign({}, common, {
      kind: 'nudge',
      subject: 'Quick reminder: deposit for ' + (r.event_type || 'event') + ' on ' + (r.event_date || ''),
      body: 'Hi ' + (r.client_name || 'there') + ',\n\nA quick reminder that the 30 percent deposit for your ' + (r.event_type || '') + ' event on ' + (r.event_date || '') + ' is still pending. The deposit confirms your date.\n\nReply to this email if you already paid or have questions.\n\nBest regards,\nThe Catering Team',
      tg_text: 'Deposit overdue for ' + (r.event_id || '') + ' (' + (r.client_name || '') + ', event ' + (r.event_date || '') + ').',
      comm_type: 'nudge', direction: 'to_client', has_email: true, _nudge: true}));
  }
}
if (actions.length === 0) {
  actions.push({kind: 'allclear', event_id: '', client_name: '', client_email: '', event_type: '', event_date: '', guest_count: 0, venue: '',
                subject: '', body: '', tg_text: 'Catering sweep ' + todayISO + ': all open events on track. No countdown or deposit actions needed.',
                comm_type: 'allclear', direction: 'to_owner', has_email: false, _nudge: false});
}
return actions.map(a => ({json: a}));
